/**
 * @summary Account transactions
 */
export const getGetAccountTransactionsUrl = (
  id: string,
  params?: GetAccountTransactionsParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/accounts/${id}/transactions?${stringifiedParams}`
    : `/api/accounts/${id}/transactions`;
};

export const getAccountTransactions = async (
  id: string,
  params?: GetAccountTransactionsParams,
  options?: RequestInit,
): Promise<TransactionList> => {
  return customFetch<TransactionList>(
    getGetAccountTransactionsUrl(id, params),
    {
      ...options,
      method: "GET",
    },
  );
};

export const getGetAccountTransactionsQueryKey = (
  id: string,
  params?: GetAccountTransactionsParams,
) => {
  return [
    `/api/accounts/${id}/transactions`,
    ...(params ? [params] : []),
  ] as const;
};

